/**
 * Owner-authorized 50-business portfolio reset (2026-08-10).
 * 25 cashflow (short path to stranger checkout) + 25 empire (wedge → platform).
 * FORGE may later improve names/prices/UX from evidence — never fabricate social proof.
 */

import type { BusinessOpportunity } from "../modules/portfolio-architect";

export type PortfolioClass = "cashflow" | "empire";

export type Portfolio50Spec = Omit<
  BusinessOpportunity,
  "id" | "score" | "rejectReasons" | "lifecycle" | "createdAt" | "evidence"
> & {
  portfolioClass: PortfolioClass;
  /** Empire expansion ladder (cashflow may omit). */
  empireLadder?: string[];
};

function cash(
  partial: Omit<Portfolio50Spec, "portfolioClass" | "fulfillment" | "requiresOwnerSpend">,
): Portfolio50Spec {
  return {
    ...partial,
    portfolioClass: "cashflow",
    fulfillment: "digital_download",
    requiresOwnerSpend: false,
  };
}

function empire(
  partial: Omit<Portfolio50Spec, "portfolioClass" | "fulfillment" | "requiresOwnerSpend"> & {
    empireLadder: string[];
  },
): Portfolio50Spec {
  return {
    ...partial,
    portfolioClass: "empire",
    fulfillment: "digital_download",
    requiresOwnerSpend: false,
  };
}

