export function portfolio50AsOpportunities(now = new Date().toISOString()): BusinessOpportunity[] {
  return PORTFOLIO_50_SPECS.map((spec, i) => {
    const { portfolioClass, empireLadder, ...rest } = spec;
    return {
      ...rest,
      id: `opp_reset50_${spec.siteId}`,
      evidence: [
        "Owner-authorized portfolio reset 2026-08-10",
        `class:${portfolioClass}`,
        ...(empireLadder ?? []).slice(0, 3),
        "No fabricated testimonials, scarcity, or fake traction",
      ],
      score: portfolioClass === "cashflow" ? 90 - i * 0.1 : 80 - (i - 25) * 0.1,
      rejectReasons: [],
      lifecycle: "launch_candidate",
      createdAt: now,
    };
  });
}

export function assertPortfolio50Shape(): { ok: true; cashflow: number; empire: number } | { ok: false; detail: string } {
  const ids = new Set(PORTFOLIO_50_SPECS.map((s) => s.siteId));
  if (PORTFOLIO_50_SPECS.length !== 50) return { ok: false, detail: `expected 50 got ${PORTFOLIO_50_SPECS.length}` };
  if (ids.size !== 50) return { ok: false, detail: "duplicate siteIds" };
  const cashflow = PORTFOLIO_50_SPECS.filter((s) => s.portfolioClass === "cashflow").length;
  const empire = PORTFOLIO_50_SPECS.filter((s) => s.portfolioClass === "empire").length;
  if (cashflow !== 25 || empire !== 25) return { ok: false, detail: `cashflow=${cashflow} empire=${empire}` };
  return { ok: true, cashflow, empire };
}
